// Advanced Market Data Processing - Bloomberg Style v3.0
const allItems = $input.all();
const currentDate = new Date();
const dateStr = currentDate.toLocaleDateString('es-CO', { 
  weekday: 'long', 
  year: 'numeric', 
  month: 'long', 
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  timeZone: 'America/Bogota'
});

// Helper functions
function formatNumber(num, decimals = 2) {
  if (!num || isNaN(num)) return 'N/A';
  return parseFloat(num).toFixed(decimals);
}

function calcChange(current, previous) {
  if (!previous || previous === 0 || !current) return null;
  return ((current - previous) / previous * 100).toFixed(2);
}

function formatLargeNumber(num) {
  if (!num) return 'N/A';
  if (num >= 1e9) return (num / 1e9).toFixed(2) + 'B';
  if (num >= 1e6) return (num / 1e6).toFixed(2) + 'M';
  if (num >= 1e3) return (num / 1e3).toFixed(2) + 'K';
  return num.toFixed(0);
}

function cleanText(text) {
  if (!text) return '';
  return text.replace(/<[^>]*>/g, '').replace(/&[^;]+;/g, ' ').trim().substring(0, 300);
}

// Initialize data structure
const marketData = {
  timestamp: currentDate.toISOString(),
  reportDate: dateStr,
  markets: {
    equities: {},
    commodities: {},
    forex: {}
  },
  news: {
    marketMoving: [],
    regional: {
      colombia: [],
      latinamerica: [],
      spain: [],
      global: []
    },
    sectors: {
      coffee: [],
      recycling: [],
      agriculture: []
    },
    centralBanks: []
  },
  analysis: {
    volatility: null,
    marketSentiment: null
  }
};

// Process each item
allItems.forEach((item) => {
  const json = item.json;
  const nodeName = item.nodeName || '';

  // Process Yahoo Finance data (chart format)
  if (nodeName.includes('Yahoo') && nodeName.includes('API')) {
    try {
      const chart = json.chart?.result?.[0];
      if (chart) {
        const meta = chart.meta;
        const quote = chart.indicators?.quote?.[0];

        if (meta && quote) {
          const lastIndex = quote.close?.length - 1 || 0;
          const currentPrice = quote.close?.[lastIndex];
          const previousPrice = quote.close?.[lastIndex - 1] || meta.previousClose;
          const volume = quote.volume?.[lastIndex];
          const high = quote.high?.[lastIndex];
          const low = quote.low?.[lastIndex];

          const change = currentPrice && previousPrice ? currentPrice - previousPrice : null;
          const changePercent = calcChange(currentPrice, previousPrice);

          const marketItem = {
            symbol: meta.symbol,
            price: formatNumber(currentPrice, 2),
            previousClose: formatNumber(meta.previousClose || previousPrice, 2),
            change: change ? formatNumber(change, 2) : 'N/A',
            changePercent: changePercent ? changePercent + '%' : 'N/A',
            volume: formatLargeNumber(volume),
            dayHigh: formatNumber(high, 2),
            dayLow: formatNumber(low, 2),
            currency: meta.currency || 'USD'
          };

          // Categorize by symbol
          if (nodeName.includes('S&P 500')) {
            marketData.markets.equities.sp500 = { ...marketItem, name: 'S&P 500' };
          } else if (nodeName.includes('NASDAQ')) {
            marketData.markets.equities.nasdaq = { ...marketItem, name: 'NASDAQ Composite' };
          } else if (nodeName.includes('Dow Jones')) {
            marketData.markets.equities.dowJones = { ...marketItem, name: 'Dow Jones Industrial' };
          } else if (nodeName.includes('Gold')) {
            marketData.markets.commodities.gold = { ...marketItem, name: 'Gold Futures', unit: 'USD/oz' };
          } else if (nodeName.includes('Crude Oil')) {
            marketData.markets.commodities.wti = { ...marketItem, name: 'WTI Crude Oil', unit: 'USD/barrel' };
          } else if (nodeName.includes('Coffee')) {
            marketData.markets.commodities.coffeeArabica = { ...marketItem, name: 'Coffee Arabica Futures', unit: 'USD/lb' };
          } else if (nodeName.includes('VIX')) {
            const vixValue = parseFloat(currentPrice);
            marketData.analysis.volatility = {
              ...marketItem,
              name: 'CBOE Volatility Index (VIX)',
              interpretation: vixValue > 25 ? 'Alta Volatilidad' : vixValue > 15 ? 'Elevada' : vixValue > 12 ? 'Normal' : 'Baja Volatilidad',
              signal: vixValue > 25 ? '⚠️ Miedo' : vixValue > 15 ? '⚡ Precaución' : '✅ Calma'
            };
          }
        }
      }
    } catch (e) {
      console.log('Error processing Yahoo Finance data:', e.message);
    }
  }

  // Process Frankfurter Forex data
  if (nodeName.includes('Forex') || nodeName.includes('Frankfurter')) {
    const rates = json.rates || {};
    if (rates && Object.keys(rates).length > 0) {
      marketData.markets.forex = {
        timestamp: json.date || currentDate.toISOString().split('T')[0],
        baseCurrency: json.base || 'USD',
        rates: {
          COP: { rate: formatNumber(rates.COP, 2), name: 'Peso Colombiano', symbol: 'USD/COP' },
          EUR: { rate: formatNumber(rates.EUR, 4), name: 'Euro', inverse: formatNumber(1 / rates.EUR, 4), symbol: 'EUR/USD' },
          MXN: { rate: formatNumber(rates.MXN, 2), name: 'Peso Mexicano', symbol: 'USD/MXN' },
          BRL: { rate: formatNumber(rates.BRL, 2), name: 'Real Brasileño', symbol: 'USD/BRL' },
          GBP: { rate: formatNumber(rates.GBP, 4), name: 'Libra Esterlina', inverse: formatNumber(1 / rates.GBP, 4), symbol: 'GBP/USD' },
          JPY: { rate: formatNumber(rates.JPY, 2), name: 'Yen Japonés', symbol: 'USD/JPY' },
          CHF: { rate: formatNumber(rates.CHF, 4), name: 'Franco Suizo', symbol: 'USD/CHF' },
          CAD: { rate: formatNumber(rates.CAD, 4), name: 'Dólar Canadiense', symbol: 'USD/CAD' }
        }
      };
    }
  }

  // Process TRM Colombia (Datos Abiertos)
  if (nodeName.includes('TRM Colombia')) {
    if (Array.isArray(json) && json.length > 0) {
      const trmData = json[0];
      if (trmData.valor) {
        marketData.markets.forex.rates = marketData.markets.forex.rates || {};
        marketData.markets.forex.rates.COP = marketData.markets.forex.rates.COP || {};
        marketData.markets.forex.rates.COP.official = {
          trm: formatNumber(parseFloat(trmData.valor), 2),
          source: 'Banco de la República',
          date: trmData.vigenciadesde || trmData.fecha
        };
      }
    }
  }

  // Process RSS News Items
  if (json.title && (json.link || json.url)) {
    const newsItem = {
      title: json.title,
      summary: cleanText(json.summary || json.description || json.contentSnippet || ''),
      link: json.link || json.url,
      pubDate: json.pubDate || json.published || json.isoDate || '',
      source: nodeName.replace('RSS - ', '').replace('API - ', '').replace(' (FIXED)', '').replace(' (NUEVO)', '')
    };

    // Categorize news by source
    const nodeNameLower = nodeName.toLowerCase();

    // Global Financial Markets
    if (nodeNameLower.includes('yahoo finance') || nodeNameLower.includes('investing') || 
        nodeNameLower.includes('marketwatch') || nodeNameLower.includes('cnbc')) {
      marketData.news.marketMoving.push(newsItem);
    }

    // Central Banks
    if (nodeNameLower.includes('federal reserve') || nodeNameLower.includes('ecb') || 
        nodeNameLower.includes('banco rep')) {
      marketData.news.centralBanks.push(newsItem);
    }

    // Colombia News
    if (nodeNameLower.includes('colombia') || nodeNameLower.includes('tiempo') || 
        nodeNameLower.includes('colombiano') || nodeNameLower.includes('república economía') ||
        nodeNameLower.includes('larepublica')) {
      marketData.news.regional.colombia.push(newsItem);
    }

    // LATAM News
    if (nodeNameLower.includes('latam') || nodeNameLower.includes('latinoam') || 
        nodeNameLower.includes('bbc mundo') || nodeNameLower.includes('voz de américa')) {
      marketData.news.regional.latinamerica.push(newsItem);
    }

    // Spain News
    if (nodeNameLower.includes('españa') || nodeNameLower.includes('país') || 
        nodeNameLower.includes('español') || nodeNameLower.includes('local spain')) {
      marketData.news.regional.spain.push(newsItem);
    }

    // Coffee Industry
    if (nodeNameLower.includes('coffee') || nodeNameLower.includes('sprudge') || 
        nodeNameLower.includes('grind') || nodeNameLower.includes('café')) {
      marketData.news.sectors.coffee.push(newsItem);
    }

    // Recycling/Pyrolysis
    if (nodeNameLower.includes('recycl') || nodeNameLower.includes('pyrolysis') || 
        nodeNameLower.includes('waste') || nodeNameLower.includes('plastic')) {
      marketData.news.sectors.recycling.push(newsItem);
    }

    // Agriculture
    if (nodeNameLower.includes('agro') || nodeNameLower.includes('agri') || 
        nodeNameLower.includes('fao') || nodeNameLower.includes('efe')) {
      marketData.news.sectors.agriculture.push(newsItem);
    }
  }
});

// Sort and limit news
function sortAndLimit(newsArray, limit = 8) {
  return newsArray
    .sort((a, b) => new Date(b.pubDate) - new Date(a.pubDate))
    .slice(0, limit);
}

marketData.news.marketMoving = sortAndLimit(marketData.news.marketMoving, 10);
marketData.news.centralBanks = sortAndLimit(marketData.news.centralBanks, 5);
marketData.news.regional.colombia = sortAndLimit(marketData.news.regional.colombia, 8);
marketData.news.regional.latinamerica = sortAndLimit(marketData.news.regional.latinamerica, 6);
marketData.news.regional.spain = sortAndLimit(marketData.news.regional.spain, 6);
marketData.news.sectors.coffee = sortAndLimit(marketData.news.sectors.coffee, 8);
marketData.news.sectors.recycling = sortAndLimit(marketData.news.sectors.recycling, 6);
marketData.news.sectors.agriculture = sortAndLimit(marketData.news.sectors.agriculture, 6);

// Calculate market sentiment
const equities = marketData.markets.equities;
let positiveMoves = 0;
let negativeMoves = 0;
let totalMoves = 0;

Object.values(equities).forEach(market => {
  if (market.changePercent && market.changePercent !== 'N/A') {
    totalMoves++;
    const change = parseFloat(market.changePercent);
    if (change > 0) positiveMoves++;
    if (change < 0) negativeMoves++;
  }
});

if (totalMoves > 0) {
  const positiveRatio = positiveMoves / totalMoves;
  marketData.analysis.marketSentiment = {
    positive: positiveMoves,
    negative: negativeMoves,
    neutral: totalMoves - positiveMoves - negativeMoves,
    overall: positiveRatio > 0.6 ? '📈 Alcista' : positiveRatio < 0.4 ? '📉 Bajista' : '➡️ Mixto',
    strength: positiveRatio > 0.6 || positiveRatio < 0.4 ? 'Fuerte' : 'Moderado'
  };
}

// Statistics
marketData.statistics = {
  totalDataSources: allItems.length,
  marketStatus: currentDate.getDay() >= 1 && currentDate.getDay() <= 5 ? 'Día de Trading' : 'Fin de Semana',
  equitiesTracked: Object.keys(marketData.markets.equities).length,
  commoditiesTracked: Object.keys(marketData.markets.commodities).length,
  forexPairs: marketData.markets.forex.rates ? Object.keys(marketData.markets.forex.rates).length : 0,
  newsArticles: {
    total: marketData.news.marketMoving.length + 
           marketData.news.centralBanks.length + 
           marketData.news.regional.colombia.length + 
           marketData.news.regional.latinamerica.length + 
           marketData.news.regional.spain.length +
           marketData.news.sectors.coffee.length +
           marketData.news.sectors.recycling.length +
           marketData.news.sectors.agriculture.length,
    byCategory: {
      marketMoving: marketData.news.marketMoving.length,
      centralBanks: marketData.news.centralBanks.length,
      colombia: marketData.news.regional.colombia.length,
      latinamerica: marketData.news.regional.latinamerica.length,
      spain: marketData.news.regional.spain.length,
      coffee: marketData.news.sectors.coffee.length,
      recycling: marketData.news.sectors.recycling.length,
      agriculture: marketData.news.sectors.agriculture.length
    }
  }
};

return [marketData];

// Format Bloomberg-Style HTML Report v3.0
const analysisData = $input.item.json;
const reportDate = new Date().toLocaleDateString('es-CO', { 
  weekday: 'long', 
  year: 'numeric', 
  month: 'long', 
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  timeZone: 'America/Bogota'
});

// Extract AI analysis content
let aiAnalysis = '';
if (analysisData.message && analysisData.message.content) {
  aiAnalysis = analysisData.message.content;
} else if (analysisData.content) {
  aiAnalysis = analysisData.content;
} else if (typeof analysisData === 'string') {
  aiAnalysis = analysisData;
}

// Enhanced markdown to HTML conversion
function markdownToHtml(text) {
  return text
    // Tables
    .replace(/\|(.+)\|/gm, (match) => {
      const cells = match.split('|').filter(c => c.trim());
      const isHeader = match.includes('---');
      if (isHeader) return '';
      const cellType = match.includes('Índice') || match.includes('Activo') || match.includes('Par') ? 'th' : 'td';
      return '<tr>' + cells.map(c => `<${cellType} style="padding: 10px; border-bottom: 1px solid #e0e0e0;">${c.trim()}</${cellType}>`).join('') + '</tr>';
    })
    // Headers
    .replace(/### (.+)/g, '<h3 style="color: #1a1a1a; font-size: 16px; margin-top: 20px; margin-bottom: 10px; font-weight: 600;">$1</h3>')
    .replace(/## (.+)/g, '<h2 style="color: #000; font-size: 20px; margin-top: 28px; margin-bottom: 14px; font-weight: 700; border-bottom: 2px solid #0066cc; padding-bottom: 6px;">$1</h2>')
    .replace(/# (.+)/g, '<h1 style="color: #000; font-size: 24px; margin-top: 0; margin-bottom: 16px; font-weight: 700;">$1</h1>')
    // Bold and italic
    .replace(/\*\*(.+?)\*\*/g, '<strong style="font-weight: 600;">$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    // Lists
    .replace(/^- (.+)$/gm, '<li style="margin: 4px 0; line-height: 1.5;">$1</li>')
    .replace(/^\d+\. (.+)$/gm, '<li style="margin: 4px 0; line-height: 1.5;">$1</li>')
    // Horizontal rules
    .replace(/---/g, '<hr style="border: none; border-top: 1px solid #e0e0e0; margin: 20px 0;">')
    // Line breaks
    .replace(/\n\n/g, '</p><p style="margin: 10px 0; line-height: 1.6;">')
    .replace(/\n/g, '<br>')
    // Code blocks
    .replace(/```[\s\S]*?```/g, '');
}

const htmlContent = `
<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Market Intelligence - ${reportDate}</title>
    <style>
        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif; line-height: 1.5; color: #1a1a1a; background: #f5f5f5; margin: 0; padding: 0; }
        .wrapper { max-width: 750px; margin: 0 auto; background: #fff; }
        .header { background: linear-gradient(135deg, #000 0%, #1a1a1a 100%); color: #fff; padding: 30px; border-bottom: 4px solid #f7931a; }
        .header-logo { font-size: 12px; font-weight: 700; letter-spacing: 2px; color: #f7931a; margin-bottom: 8px; }
        .header h1 { font-size: 26px; margin: 0 0 6px 0; }
        .header-date { font-size: 13px; color: #ccc; }
        .content { padding: 30px; }
        .footer { background: #f8f9fa; padding: 25px; text-align: center; border-top: 1px solid #e0e0e0; font-size: 11px; color: #666; }
        table { width: 100%; border-collapse: collapse; margin: 15px 0; font-size: 13px; }
        th { background: #f8f9fa; font-weight: 600; text-align: left; }
        ul { margin: 10px 0; padding-left: 20px; }
        @media (max-width: 600px) { .header, .content, .footer { padding: 20px; } .header h1 { font-size: 22px; } }
    </style>
</head>
<body>
    <div class="wrapper">
        <div class="header">
            <div class="header-logo">MARKET INTELLIGENCE</div>
            <h1>📊 Informe Diario de Mercados</h1>
            <div class="header-date">${reportDate}</div>
        </div>
        <div class="content">
            ${markdownToHtml(aiAnalysis)}
        </div>
        <div class="footer">
            <strong>Sistema de Inteligencia de Mercado v3.0</strong><br>
            Powered by n8n + OpenAI | Fuentes públicas gratuitas<br><br>
            <em>Este reporte es informativo y no constituye asesoría de inversión.</em>
        </div>
    </div>
</body>
</html>
`;

// Dynamic subject line
let subjectPrefix = '📊';
const lowerAnalysis = aiAnalysis.toLowerCase();
if (lowerAnalysis.includes('bajista') || lowerAnalysis.includes('caída') || lowerAnalysis.includes('pérdida')) {
  subjectPrefix = '📉';
} else if (lowerAnalysis.includes('alcista') || lowerAnalysis.includes('subi') || lowerAnalysis.includes('ganancia')) {
  subjectPrefix = '📈';
}

const dateForSubject = new Date().toLocaleDateString('es-CO', { day: 'numeric', month: 'short' });

return [{
  subject: `${subjectPrefix} Inteligencia de Mercado - ${dateForSubject}`,
  htmlContent: htmlContent,
  textContent: aiAnalysis,
  reportDate: reportDate,
  timestamp: new Date().toISOString()
}];
